using System;
using System.Linq;
using Revora;
using Revora.Client;
using Revora.Database;
using Revora.Game;
using Revora.Network.GamePackets;
using Console=System.Console;
internal static partial class CheckCandidateArenaLifecycle {
    static string FreshWarriorPeerSnapshot(GameState p,GameState[] players,GameState peer){return Convert.ToString(Sql("SELECT json_build_object('prior',@prior::json,'peer',(SELECT row_to_json(r) FROM (SELECT uid,name,owner,class,level,reborn,experience,atributes,strength,agility,spirit,vitality,mapid,x,y,conquerpoints,boundcps,money FROM entities WHERE uid=@uid) r),'items',(SELECT json_agg(r ORDER BY uid) FROM items r WHERE entityid=@uid),'creation',(SELECT json_agg(r) FROM revora_character_creation r WHERE character_uid=@uid),'starter',(SELECT json_agg(r ORDER BY reborn,milestone) FROM revora_custom_starter_claims r WHERE uid=@uid),'allowance',(SELECT row_to_json(r) FROM revora_exp_ball_days r WHERE uid=@uid),'evidence',(SELECT json_agg(r ORDER BY achievement_id) FROM revora_achievement_evidence r WHERE uid=@uid))::text","prior",FreshBpSnapshot(p,players),"uid",(long)peer.Entity.UID));}
    static void FreshWarriorPeerSave(GameState p,GameState[] players,GameState peer){foreach(var who in players.Concat(new[]{peer}))Require(EntityTable.SaveEntity(who));Sql("UPDATE revora_fresh_warrior_peer_probe SET snapshot=@snapshot","snapshot",FreshWarriorPeerSnapshot(p,players,peer));}
    static void FreshWarriorPeer(string phase){
        var p=FreshLoadSaved(true,true,true,true,true);EntityVariableTable.Load(p);SubClassTable.Load(p.Entity);ChiTable.Load(p);p.Quests.Load();Revora.Database.KnownPersons.LoadMentor(p);WayofHeroes.Load(p);
        var list=new System.Collections.Generic.List<GameState>();foreach(int slot in new[]{1,2,3,0}){uint uid=Convert.ToUInt32(Sql("SELECT uid FROM revora_fresh_contributors WHERE slot=@slot","slot",slot));list.Add(FreshContributor(uid,Convert.ToString(Sql("SELECT name FROM revora_fresh_contributors WHERE slot=@slot","slot",slot))));}list.Add(p);var players=list.ToArray();Server.GamePool=players;Call(typeof(Revora.Database.JiangHu),"LoadClient",p);Require(players.All(w=>!w.Fake && w.Account.State==AccountTable.AccountState.Player && !PirateFenced(w)) && p.Entity.Class==25);

        Revora.Database.KnownPersons.LoadPartner(p);Revora.Database.KnownPersons.LoaderFriends(p);GameState peer;
        if(phase.EndsWith("create")){
            Require((bool)Sql("SELECT to_regclass('revora_fresh_warrior_peer_probe') IS NULL") && FreshBpSnapshot(p,players)==Convert.ToString(Sql("SELECT snapshot FROM revora_fresh_bp_probe WHERE stage=3")) && (long)Sql("SELECT count(*) FROM accounts WHERE lower(username)='freshwar1'")==0);
            peer=FreshStarterSession();peer.Account.Username="FreshWar1";peer.Account.Password=Guid.NewGuid().ToString("N");peer.Account.Insert();Require(peer.Account.Password=="");string message="";Require(EntityTable.CreateEntity(new EnitityCreate{Name="FreshWar1",Body=2001,Class=7},peer,ref message) && message=="ANSWER_OK");FreshContributorLoad(peer);Require(peer.Entity.Level==1 && peer.Entity.Class==20 && peer.Entity.Reborn==0);Call(Feature("RevoraStarterPack"),"OnLogin",peer);ItemHandler.UseItem(peer.Inventory.Objects.Single(i=>i.ID==727990),peer);Require(peer.Entity.BoundCps==50000 && peer.Entity.Money==1100000);
            Server.GamePool=players.Concat(new[]{peer}).ToArray();p.Entity.Teleport(1002,304,435);peer.Entity.Teleport(1002,305,435);uint cp=p.Entity.ConquerPoints,other=peer.Entity.ConquerPoints;Require(cp>=20000);CareerTradePacket(p,Trade.Request,peer.Entity.UID);CareerTradePacket(peer,Trade.Request,p.Entity.UID);Require(p.Trade.InTrade && peer.Trade.InTrade);CareerTradePacket(p,Trade.SetConquerPoints,20000);CareerTradePacket(p,Trade.Accept,0);CareerTradePacket(peer,Trade.Accept,0);Require(p.Entity.ConquerPoints==cp-20000 && peer.Entity.ConquerPoints==other+20000 && !p.Trade.InTrade && !peer.Trade.InTrade);
            Sql("CREATE TABLE revora_fresh_warrior_peer_probe(uid bigint,balls int,spent bigint,capped int,done boolean,snapshot text);INSERT INTO revora_fresh_warrior_peer_probe VALUES(@uid,0,0,0,false,NULL)","uid",(long)peer.Entity.UID);FreshWarriorPeerSave(p,players,peer);
        }else{
            peer=FreshContributor(Convert.ToUInt32(Sql("SELECT uid FROM revora_fresh_warrior_peer_probe")),"FreshWar1");Server.GamePool=players.Concat(new[]{peer}).ToArray();Require(FreshWarriorPeerSnapshot(p,players,peer)==Convert.ToString(Sql("SELECT snapshot FROM revora_fresh_warrior_peer_probe")));
            if(phase.EndsWith("train")){
                Require(!(bool)Sql("SELECT done FROM revora_fresh_warrior_peer_probe"));int balls=(int)Sql("SELECT balls FROM revora_fresh_warrior_peer_probe"),initial=balls;DateTime day=new DateTime(2041,8,13,12,0,0,DateTimeKind.Local);Feature("ExperienceConsumables").GetField("Clock",Hidden).SetValue(null,(Func<DateTime>)(()=>day));var timer=System.Diagnostics.Stopwatch.StartNew();
                while(peer.Entity.Level<130 && balls-initial<160 && timer.Elapsed.TotalSeconds<210){
                    day=new DateTime(2041,8,13,12,0,0,DateTimeKind.Local).AddDays(balls/10);peer.Entity.Teleport(1002,304,435);uint cp=peer.Entity.ConquerPoints;var old=peer.Inventory.Objects.Select(i=>i.UID).ToArray();CareerBuy(peer,723700);var ball=peer.Inventory.Objects.Single(i=>!old.Contains(i.UID));uint cost=cp-peer.Entity.ConquerPoints;Require(cost==ConquerItemInformation.BaseInformations[723700].ConquerPointsWorth);
                    if(balls>0 && balls%10==0){day=day.AddDays(-1);byte level=peer.Entity.Level;ulong xp=peer.Entity.Experience;ItemHandler.UseItem(ball,peer);Require(peer.Entity.Level==level && peer.Entity.Experience==xp && peer.Inventory.ContainsUID(ball.UID));day=day.AddDays(1);Sql("UPDATE revora_fresh_warrior_peer_probe SET capped=capped+1");}
                    byte before=peer.Entity.Level;ulong beforeXp=peer.Entity.Experience;ItemHandler.UseItem(ball,peer);Require(!peer.Inventory.ContainsUID(ball.UID) && (peer.Entity.Level>before || peer.Entity.Experience>beforeXp) && !PirateFenced(peer));balls++;Require((bool)Sql("SELECT used=@used AND day=@day FROM revora_exp_ball_days WHERE uid=@uid","used",balls%10==0?10:balls%10,"day",day.Year*10000+day.Month*100+day.Day,"uid",(long)peer.Entity.UID));Sql("UPDATE revora_fresh_warrior_peer_probe SET balls=@balls,spent=spent+@cost,done=@done","balls",balls,"cost",(long)cost,"done",peer.Entity.Level>=130);FreshWarriorPeerSave(p,players,peer);string once=FreshWarriorPeerSnapshot(p,players,peer);ItemHandler.UseItem(ball,peer);Require(once==FreshWarriorPeerSnapshot(p,players,peer));
                }
            }else Require(phase.EndsWith("reload") && (bool)Sql("SELECT done FROM revora_fresh_warrior_peer_probe") && peer.Entity.Level>=130 && peer.Entity.Class>=20 && peer.Entity.Class<=25 && (int)Call(Feature("LocalPkWar"),"Bracket",(int)peer.Entity.Level)==(int)Call(Feature("LocalPkWar"),"Bracket",(int)p.Entity.Level));
        }
        Require(!peer.Fake && peer.Account.State==AccountTable.AccountState.Player && FreshWarriorPeerSnapshot(p,players,peer)==Convert.ToString(Sql("SELECT snapshot FROM revora_fresh_warrior_peer_probe")));Console.WriteLine("[career-process] "+phase+"-passed level="+peer.Entity.Level+" balls="+Sql("SELECT balls FROM revora_fresh_warrior_peer_probe")+" cp="+Sql("SELECT spent FROM revora_fresh_warrior_peer_probe")+" done="+Sql("SELECT done FROM revora_fresh_warrior_peer_probe"));Console.Out.Flush();Environment.Exit(0);
    }
}
